from django.db import migrations, models


# 대표 약제 외 추가 연관 약제 — apps.genomics.services.EXTRA_VARIANT_DRUGS 와 같은 값(마이그레이션은 앱 코드에 의존하지 않도록 복사)
EXTRA = {
    "rrs a1401g": ["Amikacin", "Kanamycin", "Capreomycin"],
    "inhA c-15t": ["Isoniazid", "Ethionamide"],
    "eis c-14t": ["Kanamycin"],
}


def fill_drugs(apps, schema_editor):
    """기존 행 보정(멱등): drugs = [대표 약제] + 추가 연관(중복 없이). 이미 들어 있는 약제는 유지한다."""
    Variant = apps.get_model("genomics", "Variant")
    for v in Variant.objects.all():
        cur = [d for d in (v.drugs or []) if isinstance(d, str)]
        want = list(dict.fromkeys([v.drug_resistance] + EXTRA.get(v.label, []) + cur))
        if want != cur:
            v.drugs = want
            v.save(update_fields=["drugs"])


